/** a data table inside a section: scrolls horizontally on narrow screens */
export type BlogTable = { caption?: string; head: string[]; rows: string[][]; note?: string };
/** the store block after the FAQ: heading, lines (inline links allowed), fine print */
export type BlogVisit = { heading: string; lines: string[]; fine?: string };
/** a list inside a section: check-icon bullets (SVG) or a numbered list */
export type BlogList = { style: 'check' | 'number'; items: string[] };
/** the ordered content of a section: paragraphs, sub-headings (h3), lists and tables in the order written */
export type BlogBlock = { p: string } | { h3: string } | { list: BlogList } | { table: BlogTable };

export type BlogSection = {
  heading?: string; // rendered as <h2>; the intro has none
  paragraphs: string[]; // the section's paragraphs (used when `blocks` is absent)
  blocks?: BlogBlock[]; // mixed content in order; replaces `paragraphs` for rendering when present
  table?: BlogTable; // rendered after the paragraphs, before the image
  image?: BlogImage & { caption?: string }; // supporting image shown after the section
};

export type BlogFaq = { question: string; answer: string };
export type BlogSource = { label: string; href: string }; // cited source, rendered under the article

export type BlogPost = {
  slug: string;
  /** the slug of the same post in the other language when it differs; undefined = same slug */
  altSlug?: string;
  title: string; // <h1> + BlogPosting.headline
  metaTitle: string; // ≤ 60 chars, ends "| Snooze Mattress"
  metaDescription: string; // ≤ 155 chars
  keywords: string[];
  datePublished: string; // ISO date
  dateModified?: string; // ISO date of the last content refresh (BlogPosting.dateModified, og:modified_time, sitemap lastmod)
  dateDisplay: string; // as shown on the page
  readTime?: string; // as given by the client; computed from the word count when absent (readTimeOf)
  featured: BlogImage;
  featuredFit?: 'contain'; // show the whole featured image instead of cropping it to the banner height
  excerpt: string; // first sentence of the post, verbatim — used on cards
  sections: BlogSection[];
  /** the client's closing line ("Stop Guessing. Start Sleeping."): a styled paragraph after the article, not a heading */
  tagline?: string;
  faqs: BlogFaq[];
  visit?: BlogVisit; // store block between the FAQ and the sources
  sources?: BlogSource[]; // "Sources" list after the FAQ
};

