export { POSTS_ES };

export type BlogLocale = 'en' | 'es';
export const postsFor = (locale: BlogLocale = 'en') => (locale === 'es' ? POSTS_ES : POSTS);
export const getPost = (slug: string, locale: BlogLocale = 'en') => postsFor(locale).find((p) => p.slug === slug);
/** newest first; posts published the same day keep their order in POSTS (the document's order) */
export const byNewest = (a: BlogPost, b: BlogPost) => b.datePublished.localeCompare(a.datePublished);
/** the two newest other posts */
export const relatedPosts = (slug: string, locale: BlogLocale = 'en') =>
  [...postsFor(locale)].filter((p) => p.slug !== slug).sort(byNewest).slice(0, 2);
/** the post's path in the other language (its altSlug when the slug differs per language) */
export const altBlogPath = (post: BlogPost) => `/blog/${post.altSlug || post.slug}`;

/* ---- text helpers (word count for the schema, reading time for the byline) ---- */
const stripInline = (s: string) => s.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').replace(/\*\*([^*]+)\*\*/g, '$1').replace(/_([^_]+)_/g, '$1');
export const sectionText = (s: BlogSection): string[] => {
  if (!s.blocks) return [...s.paragraphs, ...(s.table ? s.table.rows.flat() : [])];
  return s.blocks.flatMap((b) => ('p' in b ? [b.p] : 'h3' in b ? [b.h3] : 'list' in b ? b.list.items : [...b.table.head, ...b.table.rows.flat()]));
};
export const wordCountOf = (post: BlogPost) => post.sections.flatMap(sectionText).map(stripInline).join(' ').split(/\s+/).filter(Boolean).length;
export const readTimeOf = (post: BlogPost, locale: BlogLocale = 'en') => {
  if (post.readTime) return post.readTime;
  const min = Math.max(1, Math.round(wordCountOf(post) / 200));
  return locale === 'es' ? `${min} min de lectura` : `${min} min read`;
};
